  function peopleExportRows(){return people.map(person=>({id:String(person.id),values:[person.full_name||'',profilePhotoState(person),organizationRole(person),organizationPosition(person),systemAccess(person),person.gender||'—',person.email||'—',person.login_name||'—',credentialExportState(person),person.salutation||'—',person.active!==false?'بله':'خیر']}))}
