/* source: assets/js/stickers.js */
/* Sticker library manager: preloaded, empty-safe, paired preview, user-owned packs. */
(()=>{'use strict';
const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)],STATES=['state1','state2','state3','state4','state5'],META={state1:'وضعیت مطلوب',state2:'یادآوری',state3:'نیازمند توجه',state4:'پیگیری جدی',state5:'اقدام فوری'},SIDES=[['female','خانم'],['male','آقا']],esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let sets=[],rows=[],files=new Map(),pickKey='',renderEpoch=0,warmEpoch=0,editingSet=null,rowsSetId=0,loaded=false,loadPromise=null;const rowsBySet=new Map();

function install(){
 let view=q('#stickersView');if(!view){view=document.createElement('section');view.id='stickersView';view.className='view hidden manager-only';q('.workspace')?.append(view)}
 if(view.dataset.stickerManager==='1')return;view.dataset.stickerManager='1';
 view.innerHTML=`<div class="panel sticker-library"><div class="panel-head"><div><h3>مدیریت استیکرها</h3><small>هر وضعیت با دو تصویر کنار هم نمایش داده می‌شود.</small></div></div><div class="sticker-toolbar"><div class="sticker-selectors"><label>نسخه <select id="stickerSet"><option>در حال آماده‌سازی…</option></select></label><label>وضعیت <select id="stickerState">${STATES.map(k=>`<option value="${k}">${META[k]}</option>`).join('')}</select></label></div><button id="stickerActivate" class="ghost" type="button">فعال‌سازی نسخه</button><button id="stickerNew" class="ghost" type="button">افزودن نسخه</button><button id="stickerEdit" class="ghost" type="button">ویرایش نسخه</button></div><div id="stickerEmpty" class="sticker-empty hidden"><strong>هنوز استیکری تعریف نشده است</strong><span>برای ساخت نخستین نسخه، «افزودن نسخه» را بزنید.</span></div><div id="stickerPair" class="sticker-pair"><article><div class="sticker-image-loading">در حال آماده‌سازی…</div><strong>خانم</strong></article><article><div class="sticker-image-loading">در حال آماده‌سازی…</div><strong>آقا</strong></article></div></div>`;
 if(!q('#stickerPackDialog'))document.body.insertAdjacentHTML('beforeend',`<dialog id="stickerPackDialog" class="modal sticker-pack-dialog"><form id="stickerPackForm"><div class="modal-head"><div><h3>نسخه جدید استیکر</h3><p>برای هر وضعیت، دو تصویر را انتخاب کنید.</p></div><button type="button" data-sticker-close aria-label="بستن">×</button></div><label class="sticker-pack-name" for="stickerPackName"><span>نام نسخه</span><input id="stickerPackName" required maxlength="120"></label><div class="sticker-upload-grid"><b>وضعیت</b>${SIDES.map(([,l])=>`<b>${l}</b>`).join('')}${STATES.map(k=>`<span>${META[k]}</span>${SIDES.map(([g])=>`<button class="ghost sticker-pick" type="button" data-key="${k}_${g}">انتخاب تصویر</button>`).join('')}`).join('')}</div><input id="stickerFile" type="file" accept="image/png,image/jpeg,image/webp" hidden><div class="modal-actions"><button type="button" class="ghost" data-sticker-close>انصراف</button><button id="stickerSave" class="primary">ذخیره و فعال‌سازی</button></div></form></dialog>`);
 q('#stickerSet').onchange=()=>loadRows().catch(e=>toast(e.message,true));q('#stickerState').onchange=renderPair;q('#stickerNew').onclick=()=>openPack(false);q('#stickerEdit').onclick=()=>openPack(true).catch(e=>toast(e.message,true));q('#stickerActivate').onclick=activate;qa('[data-sticker-close]').forEach(b=>b.onclick=()=>q('#stickerPackDialog').close());qa('.sticker-pick').forEach(b=>b.onclick=()=>{pickKey=b.dataset.key;q('#stickerFile').value='';q('#stickerFile').click()});q('#stickerFile').onchange=chooseFile;q('#stickerPackForm').onsubmit=savePack;
}

async function authUrl(path){if(!window.bamcoMedia?.get)throw Error('سرویس تصویر آماده نیست.');return window.bamcoMedia.get('stickers',String(path))}

function warmImages(list=rows){
 const epoch=++warmEpoch,k=q('#stickerState')?.value||'state1',currentSet=rowsSetId;
 const preferred=sets.filter(s=>Number(s.id)!==currentSet).flatMap(s=>(rowsBySet.get(Number(s.id))||[]).filter(r=>r.state_key===k));
 const remaining=list.filter(r=>r.state_key!==k),queue=[...preferred,...remaining];let index=0;
 const next=()=>{if(epoch!==warmEpoch||index>=queue.length)return;authUrl(queue[index++].storage_path).catch(()=>{}).finally(()=>{if(epoch===warmEpoch)setTimeout(next,120)})};
 setTimeout(next,250);
}

async function renderPair(){const box=q('#stickerPair');if(!box)return;const k=q('#stickerState')?.value||'state1',epoch=++renderEpoch;++warmEpoch;box.innerHTML=SIDES.map(([g,l])=>`<article data-side="${g}"><div class="sticker-image-loading">در حال دریافت…</div><strong>${l}</strong></article>`).join('');const jobs=SIDES.map(async([g])=>{const card=q(`[data-side="${g}"]`,box),row=rows.find(x=>x.state_key===k&&x.gender===g);if(!row){card.querySelector('div').textContent='تصویری تعریف نشده است';return}try{const src=await authUrl(row.storage_path);if(epoch!==renderEpoch||!card.isConnected)return;const img=document.createElement('img');img.src=src;img.alt=META[k];card.querySelector('div').replaceWith(img)}catch(err){if(epoch===renderEpoch&&card.isConnected)card.querySelector('div').textContent=err.message}});await Promise.all(jobs);if(epoch===renderEpoch)warmImages()}

async function loadRows(){const id=Number(q('#stickerSet')?.value||0);rows=id?(rowsBySet.get(id)||[]):[];rowsSetId=id;await renderPair()}

async function doLoad(preferredId=null,force=false){
 const combo=q('#stickerSet'),empty=q('#stickerEmpty'),pair=q('#stickerPair');if(!combo)return;
 if(loaded&&!force&&!preferredId){void renderPair();return}
 sets=await select('sticker_sets','select=*&order=created_at.asc');
 if(!sets.length){combo.innerHTML='<option value="">نسخه‌ای ثبت نشده است</option>';combo.disabled=true;q('#stickerActivate').disabled=true;q('#stickerEdit').disabled=true;empty.classList.remove('hidden');pair.innerHTML='';loaded=true;return}
 const allRows=await select('stickers','select=*&order=set_id,state_key,gender');rowsBySet.clear();for(const row of allRows){const id=Number(row.set_id);if(!rowsBySet.has(id))rowsBySet.set(id,[]);rowsBySet.get(id).push(row)}
 combo.disabled=false;q('#stickerActivate').disabled=false;q('#stickerEdit').disabled=false;empty.classList.add('hidden');const active=sets.find(x=>Number(x.id)===Number(preferredId))||sets.find(x=>x.active)||sets[0];combo.innerHTML=sets.map(x=>`<option value="${x.id}" ${Number(x.id)===Number(active.id)?'selected':''}>${esc(x.name)}${x.active?' — فعال':''}</option>`).join('');rowsSetId=0;await loadRows();loaded=true;
}
function load(preferredId=null,force=false){if(loadPromise&&!force)return loadPromise;loadPromise=doLoad(preferredId,force).finally(()=>{loadPromise=null});return loadPromise}

async function openPack(edit){editingSet=edit?Number(q('#stickerSet').value):null;if(edit&&!editingSet)return;files.clear();if(edit)await loadRows();q('#stickerPackName').value=edit?sets.find(x=>Number(x.id)===editingSet)?.name||'':'';q('#stickerPackDialog h3').textContent=edit?'ویرایش نسخه استیکر':'نسخه جدید استیکر';q('#stickerSave').textContent=edit?'ذخیره تغییرات':'ذخیره و فعال‌سازی';qa('.sticker-pick').forEach(b=>{const [key,gender]=b.dataset.key.split('_'),exists=edit&&rows.some(x=>x.state_key===key&&x.gender===gender);b.textContent=exists?'تغییر تصویر':'انتخاب تصویر';b.classList.toggle('selected',!!exists)});q('#stickerPackDialog').showModal()}
function chooseFile(e){const f=e.target.files?.[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5*1024*1024){toast('تصویر باید PNG، JPG یا WebP و حداکثر ۵ مگابایت باشد.',true);return}files.set(pickKey,f);const b=q(`[data-key="${pickKey}"]`);b.textContent='✓ انتخاب شد';b.classList.add('selected')}
async function upload(setId,key,file){const [stateKey,gender]=key.split('_'),ext=file.type==='image/jpeg'?'jpg':file.type==='image/webp'?'webp':'png',path=`sets/${setId}/${stateKey}_${gender}_${crypto.randomUUID()}.${ext}`,encoded=path.split('/').map(encodeURIComponent).join('/'),res=await fetch(`${SB_URL}/storage/v1/object/stickers/${encoded}`,{method:'POST',headers:{apikey:SB_KEY,Authorization:`Bearer ${state.token}`,'x-upsert':'true','Content-Type':file.type},body:file});if(!res.ok)throw Error('بارگذاری یکی از تصاویر انجام نشد.');const payload={set_id:setId,state_key:stateKey,gender,storage_path:path,mime_type:file.type,size_bytes:file.size,sha256:null},existing=rows.find(x=>Number(x.set_id)===Number(setId)&&x.state_key===stateKey&&x.gender===gender);const saved=existing?await update('stickers',`id=eq.${existing.id}`,payload):await insert('stickers',payload);if(!saved?.length)throw Error('ذخیره تصویر تأیید نشد.')}
async function savePack(e){e.preventDefault();const name=q('#stickerPackName').value.trim(),required=STATES.flatMap(k=>SIDES.map(([g])=>`${k}_${g}`)),id=editingSet;if(!name)return toast('نام نسخه را وارد کنید.',true);if(required.some(k=>!files.has(k)&&(!id||!rows.some(x=>`${x.state_key}_${x.gender}`===k))))return toast('هر ده تصویر نسخه باید انتخاب شوند.',true);const b=q('#stickerSave');if(b.disabled)return;b.disabled=true;try{const saved=id?await update('sticker_sets',`id=eq.${id}`,{name}):await insert('sticker_sets',{name,active:false,system_set:false,created_by:state.profile.id});if(!saved?.length)throw Error('ذخیره نسخه تأیید نشد.');const setId=Number(saved[0].id);for(const [key,file] of files)await upload(setId,key,file);if(!id)await rpc('activate_sticker_set',{p_set_id:setId});document.dispatchEvent(new CustomEvent('bamco:stickers-changed'));q('#stickerPackDialog').close();toast('نسخه استیکر ذخیره شد.');loaded=false;rowsSetId=0;await load(setId,true)}catch(err){toast(err.message,true)}finally{b.disabled=false}}
async function activate(){const id=Number(q('#stickerSet').value||0),button=q('#stickerActivate');if(!id||button.disabled)return;button.disabled=true;try{await rpc('activate_sticker_set',{p_set_id:id});document.dispatchEvent(new CustomEvent('bamco:stickers-changed'));toast('نسخه فعال شد.');loaded=false;await load(id,true)}catch(error){toast(error.message,true)}finally{button.disabled=false}}


function boot(){install();q('#nav button[data-view="stickers"]')?.addEventListener('click',()=>{if(loaded){void renderPair();warmImages();return}load().catch(e=>toast(e.message,true))})}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
