 async function load(force=false){if(!state?.token)return;if(!force&&Date.now()-loadedAt<15000)return;if(loading){await loading;if(force)return load(true);return}const user=state.user?.id,requestRevision=revision;loading=(async()=>{const [s,p]=await Promise.all([selectAll('task_statuses','select=*&order=sort_order,key'),selectAll('priorities','select=*&order=sort_order,key')]);if(user!==state.user?.id||requestRevision!==revision)return;const next=JSON.stringify([s,p]),changed=next!==signature;statuses=s.filter(x=>!x.merged_into);priorities=p;loadedAt=Date.now();signature=next;canonicalize();if(!q('#taskDialog')?.open)fillForm();if(changed){document.dispatchEvent(new CustomEvent('bamco:task-options'));if(state.profile&&q('#appView')&&!q('#appView').classList.contains('hidden')){renderAll();window.bamcoTimelineRefresh?.()}}})();try{return await loading}finally{loading=null}}
