  const form=q('form',d),sync=()=>{if(type!=='status')return;const k=form.elements.kind.value;for(const field of ['owner_mode','start_mode','due_mode']){const forced=k==='registered'||(k==='waiting'&&field==='due_mode');form.elements[field].disabled=forced;if(forced)form.elements[field].value='none'}const noDeadline=['registered','waiting','completed','cancelled'].includes(k)||form.elements.due_mode.value==='none';form.elements.tracks_deadline.disabled=noDeadline;if(noDeadline)form.elements.tracks_deadline.checked=false;form.elements.archivable.disabled=k==='completed';if(k==='completed')form.elements.archivable.checked=true};form.onchange=sync;sync();form.onsubmit=async e=>{e.preventDefault();const b=q('[type=submit]',form);if(b.disabled)return;b.disabled=true;q('.catalog-error',form).textContent='';try{const data={};for(const name of ['label','sort_order','color','active',...(type==='status'?['kind','owner_mode','start_mode','due_mode','tracks_deadline','archivable']:[])]){const field=form.elements[name];data[name]=field.type==='checkbox'?field.checked:field.type==='number'?Number(field.value):field.value.trim()}await save(type,key,data);d.close()}catch(error){q('.catalog-error',form).textContent=error.message}finally{b.disabled=false}};d.showModal();
