  for(const x of list){if(x.key===saved.key)continue;if(!old&&x.sort_order>=saved.sort_order)x.sort_order++;else if(oldPosition>saved.sort_order&&x.sort_order>=saved.sort_order&&x.sort_order<oldPosition)x.sort_order++;else if(oldPosition<saved.sort_order&&x.sort_order>oldPosition&&x.sort_order<=saved.sort_order)x.sort_order--}
