/* source: assets/js/tables.js */
(()=>{
  'use strict';
  const q=(s,r=document)=>r.querySelector(s),qa=(s,r=document)=>[...r.querySelectorAll(s)];
  const labels={columns:'ستون‌ها',density:'نمای فشرده',fullscreen:'تمام‌صفحه',reset:'بازنشانی جدول'};

  function tableOf(scope){return q(`#${scope}View table`)}
  function headerText(th){return (th.childNodes[0]?.textContent||th.textContent||'').trim()}

  function sortTable(table,index,direction){
    const body=table.tBodies[0];if(!body)return;
    const rows=qa('tr',body),number=s=>Number(String(s).replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/[,٬]/g,''));
    rows.sort((a,b)=>{
      const av=a.cells[index]?.innerText.trim()||'',bv=b.cells[index]?.innerText.trim()||'',an=number(av),bn=number(bv);
      const result=Number.isFinite(an)&&Number.isFinite(bn)?an-bn:av.localeCompare(bv,'fa',{numeric:true,sensitivity:'base'});
      return direction==='asc'?result:-result;
    });
    rows.forEach(row=>body.appendChild(row));
  }

  function installSort(table){
    qa('thead tr:first-child th',table).forEach((th,index)=>{
      if(th.dataset.workbenchSort==='1'||headerText(th)==='انتخاب')return;
      th.dataset.workbenchSort='1';th.classList.add('wb-sortable');th.tabIndex=0;th.title='مرتب‌سازی این ستون';
      const apply=()=>{
        const next=th.dataset.sortDirection==='asc'?'desc':'asc';
        qa('thead th',table).forEach(x=>{delete x.dataset.sortDirection;x.removeAttribute('aria-sort')});
        th.dataset.sortDirection=next;th.setAttribute('aria-sort',next==='asc'?'ascending':'descending');sortTable(table,index,next);
      };
      th.addEventListener('click',e=>{if(e.target.closest('.column-resize-handle,select,input,button'))return;apply()});
      th.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();apply()}});
    });
  }

  function toggleColumn(table,index,show){
    qa('tr',table).forEach(row=>row.cells[index]?.classList.toggle('wb-column-hidden',!show));
  }

  function columnMenu(scope,table,button){
    q('.wb-column-menu')?.remove();
    const menu=document.createElement('div');menu.className='wb-column-menu';
    qa('thead tr:first-child th',table).forEach((th,index)=>{
      const name=headerText(th);if(!name||name==='انتخاب')return;
      const label=document.createElement('label'),input=document.createElement('input');input.type='checkbox';input.checked=!th.classList.contains('wb-column-hidden');
      input.addEventListener('change',()=>toggleColumn(table,index,input.checked));label.append(input,document.createTextNode(name));menu.appendChild(label);
    });
    button.parentElement.appendChild(menu);
    const close=e=>{if(!menu.contains(e.target)&&e.target!==button){menu.remove();document.removeEventListener('pointerdown',close,true)}};
    setTimeout(()=>document.addEventListener('pointerdown',close,true));
  }

  function reset(scope,table){
    try{localStorage.removeItem(`bamco-${scope}-column-widths-v6`)}catch{}
    qa('.column-filters select',table).forEach(x=>{x.value='';x.dispatchEvent(new Event('change',{bubbles:true}))});
    qa('thead th',table).forEach((th,index)=>{th.classList.remove('wb-column-hidden');delete th.dataset.sortDirection;th.removeAttribute('aria-sort');toggleColumn(table,index,true)});
    table.closest('.table-panel')?.classList.remove('wb-compact','wb-fullscreen');
    window.dispatchEvent(new Event('resize'));
  }

  function install(scope){
    const table=tableOf(scope),panel=table?.closest('.table-panel'),toolbar=q(`#${scope}View .task-toolbar`);if(!table||!panel||!toolbar)return;
    installSort(table);
    if(toolbar.querySelector('.table-workbench'))return;
    const tools=document.createElement('div');tools.className='table-workbench';
    const make=(name,icon)=>{const b=document.createElement('button');b.type='button';b.className='ghost wb-tool';b.dataset.tool=name;b.title=labels[name];b.setAttribute('aria-label',labels[name]);b.innerHTML=`<span aria-hidden="true">${icon}</span><em>${labels[name]}</em>`;return b};
    const cols=make('columns','▥'),density=make('density','≡'),full=make('fullscreen','⛶'),clear=make('reset','↺');tools.append(cols,density,full,clear);toolbar.appendChild(tools);
    cols.onclick=()=>columnMenu(scope,table,cols);
    density.onclick=()=>{const on=panel.classList.toggle('wb-compact');density.classList.toggle('active',on)};
    full.onclick=()=>{const on=panel.classList.toggle('wb-fullscreen');full.classList.toggle('active',on);full.querySelector('em').textContent=on?'خروج از تمام‌صفحه':labels.fullscreen};
    clear.onclick=()=>reset(scope,table);
  }

  function refresh(){for(const scope of ['kanban','archive'])install(scope)}
  const boot=()=>{refresh();const targets=[q('#kanbanView'),q('#archiveView')].filter(Boolean);let raf=0;if(targets.length){const observer=new MutationObserver(()=>{if(raf)return;raf=requestAnimationFrame(()=>{raf=0;refresh()})});targets.forEach(el=>observer.observe(el,{childList:true,subtree:true}))}};
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
;

/* source: assets/js/ui-helpers.js */
/* module:ui:19 */
window.__bamcoStableStickerInstalled=true;

/* module:ui:20 */
(()=>{
  const hasFa=s=>/[\u0600-\u06ff]/.test(String(s||''));
  const hasEn=s=>/[A-Za-z]/.test(String(s||''));
  document.documentElement.dataset.uiHotfix='20260907-hq1';

  function wrapLatinText(root=document.body){
    if(!root)return;
    const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode(node){
      const p=node.parentElement;
      if(!p||!hasEn(node.nodeValue))return NodeFilter.FILTER_REJECT;
      if(p.closest('script,style,textarea,input,select,option,pre,code,.latin-run,[contenteditable="true"]'))return NodeFilter.FILTER_REJECT;
      return NodeFilter.FILTER_ACCEPT;
    }});
    const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
    nodes.forEach(node=>{
      const text=node.nodeValue||'',re=/([A-Za-z][A-Za-z0-9@._%+\-/:;#&()'\"]*)/g;
      if(!re.test(text))return;re.lastIndex=0;
      const frag=document.createDocumentFragment();let last=0,m;
      while((m=re.exec(text))){
        if(m.index>last)frag.append(document.createTextNode(text.slice(last,m.index)));
        const span=document.createElement('span');span.className='latin-run';span.textContent=m[0];frag.append(span);last=re.lastIndex;
      }
      if(last<text.length)frag.append(document.createTextNode(text.slice(last)));
      node.replaceWith(frag);
    });
  }

  function classifyControls(root=document){
    const nodes=[];
    if(root.nodeType===1&&root.matches?.('input,textarea,select,option'))nodes.push(root);
    root.querySelectorAll?.('input,textarea,select,option,.english,.en-text,[dir="ltr"]')?.forEach(el=>nodes.push(el));
    nodes.forEach(el=>{
      const text=(el instanceof HTMLInputElement||el instanceof HTMLTextAreaElement)?`${el.value||''} ${el.placeholder||''}`:(el.textContent||'');
      if((hasEn(text)&&!hasFa(text))||el.matches('.english,.en-text,[dir="ltr"]'))el.classList.add('english-ui');
      else el.classList.remove('english-ui');
    });
  }

  function installTypography(){
    const app=document.querySelector('#appView');
    if(!app||app.dataset.typographyWatcher==='1')return;
    app.dataset.typographyWatcher='1';
    let installed=false;
    const activate=()=>{
      if(installed||app.classList.contains('hidden'))return;
      installed=true;
      const run=()=>{
        classifyControls(app);
        wrapLatinText(app);
        const pending=new Set();let raf=0;
        new MutationObserver(muts=>{
          for(const m of muts){
            if(m.type!=='childList'||!m.addedNodes.length)continue;
            m.addedNodes.forEach(node=>{if(node.nodeType===1)pending.add(node)});
          }
          if(!pending.size||raf)return;
          raf=requestAnimationFrame(()=>{
            raf=0;
            const roots=[...pending];pending.clear();
            roots.forEach(root=>classifyControls(root));
          });
        }).observe(app,{childList:true,subtree:true});
      };
      if('requestIdleCallback' in window)requestIdleCallback(run,{timeout:600});
      else setTimeout(run,0);
    };
    activate();
    if(!installed)new MutationObserver((_,observer)=>{if(!app.classList.contains('hidden')){observer.disconnect();activate()}}).observe(app,{attributes:true,attributeFilter:['class']});
  }

  function clearSelection(scope){
    if(typeof state==='undefined'||!state.selected||!scope)return;
    state.selected[scope]=null;
    const view=document.querySelector(`#${scope}View`);
    view?.querySelectorAll('.task-pick').forEach(x=>x.checked=false);
    view?.querySelectorAll('tr.task-selected').forEach(x=>x.classList.remove('task-selected'));
    if(typeof updateTaskToolbar==='function')updateTaskToolbar(scope);
  }

  function installOutsideSelectionClear(){
    document.addEventListener('pointerdown',e=>{
      if(typeof state==='undefined')return;
      const scope=state.view==='archive'?'archive':state.view==='kanban'?'kanban':null;
      if(!scope||state.selected?.[scope]==null)return;
      const view=document.querySelector(`#${scope}View`);
      if(view?.querySelector('.table-wrap table')?.contains(e.target)||view?.querySelector('.task-toolbar')?.contains(e.target))return;
      clearSelection(scope);
    },true);
  }

  function installDeleteResequence(){
    if(typeof window.deleteTask!=='function')return;
    window.deleteTask=async id=>{
      if(typeof isManager==='function'&&!isManager())return;
      const task=state.tasks.find(t=>String(t.id)===String(id));
      if(!task||!await window.bamcoConfirm(`وظیفه «${task.title}» برای همیشه حذف شود؟`))return;
      try{
        await rpc('delete_tasks_and_resequence',{p_task_ids:[Number(id)]});
        state.selected.kanban=null;state.selected.archive=null;
        await refresh();toast('وظیفه حذف شد و شماره‌ها در کانبان و آرشیو بازشماری شدند.');
      }catch(err){toast(err.message,true)}
    };
  }

  function installFooter(){
    const app=document.querySelector('#appView');if(!app)return;
    let footer=document.querySelector('#appFooterCredit');
    if(!footer){
      footer=document.createElement('footer');footer.id='appFooterCredit';footer.className='app-footer-credit';
      footer.textContent='توسعه یافته توسط واحد مهندسی محصول شرکت خودروسازان بم | شهاب‌الدین تنهائیان و نازنین قائمی';
      app.appendChild(footer);
    }
  }

  function installSidebarHoverScroll(){
    const nav=document.querySelector('#sidebar nav');if(!nav||nav.dataset.hoverScroll==='1')return;
    nav.dataset.hoverScroll='1';let speed=0,raf=0;
    const tick=()=>{if(!speed){raf=0;return}nav.scrollTop+=speed;raf=requestAnimationFrame(tick)};
    const setSpeed=e=>{
      const r=nav.getBoundingClientRect();if(!r.height){speed=0;return}
      const y=(e.clientY-r.top)/r.height,edge=.22,max=5;
      if(y<edge)speed=-Math.max(1,Math.round((edge-y)/edge*max));
      else if(y>1-edge)speed=Math.max(1,Math.round((y-(1-edge))/edge*max));
      else speed=0;
      if(speed&&!raf)raf=requestAnimationFrame(tick);
    };
    nav.addEventListener('mousemove',setSpeed,{passive:true});
    nav.addEventListener('mouseleave',()=>{speed=0},{passive:true});
    nav.addEventListener('mouseenter',setSpeed,{passive:true});
  }

  function refreshStableLayout(){/* Bundled in bamco-unified.css. */}
  function installSidebarUniformStyle(){/* Bundled in bamco-unified.css. */}
  function appendOrderedScript(){/* already bundled */}
  function installGroupedSidebar(){appendOrderedScript('script[data-sidebar-groups]','sidebar-groups-20260906.js?v=20260907-core2','sidebarGroups')}
  function installUserRequestedFixesV2(){appendOrderedScript('script[data-user-request-fixes-v2]','user-request-fixes-20260907-v2.js?v=20260907-hq1','userRequestFixesV2')}
  function installLoginControls(){appendOrderedScript('script[data-login-controls]','login-controls-20260907.js?v=20260907-core2','loginControls')}
  function installFinalPolish(){appendOrderedScript('script[data-final-polish]','final-polish-20260907.js?v=20260907-core2','finalPolish')}

  const boot=()=>{
    refreshStableLayout();installSidebarUniformStyle();installTypography();installOutsideSelectionClear();installDeleteResequence();installFooter();installSidebarHoverScroll();installGroupedSidebar();installUserRequestedFixesV2();installLoginControls();installFinalPolish();
  };
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',boot,{once:true});else boot();
})();
;

