(()=>{
'use strict';
const q=(s,r=document)=>r?.querySelector(s)||null,qa=(s,r=document)=>[...(r?.querySelectorAll(s)||[])];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[c]));
const mgr=()=>typeof isManager==='function'&&isManager();
const REMOVED=new Set(['requestReport']);
const NEW=[['loginActivity','ورود و خروج','people',true],['activeSessions','نشست‌های فعال','people',true],['groupChat','گفت‌وگوی عمومی و گروه‌ها','conversations',false],['directMessages','گفت‌وگوی خصوصی','conversations',false],['taskChats','گفت‌وگوی مرتبط با وظیفه','conversations',false],['performanceReport','گزارش عملکرد','reports',true],['responseReport','گزارش پاسخ‌ها','reports',true],['systemOptions','وضعیت‌ها و اولویت‌ها','configuration',true]];
const catalog=window.BamcoNavigationCatalog;
if(!catalog)return;
const ORDER=Object.fromEntries(catalog.groups.map(group=>[group.key,group.routes]));
let installed=false;const inflight=new Map();
function purgeRemoved(){
 for(const id of REMOVED){q(`#nav button[data-view="${id}"]`)?.remove();q(`#${id}View`)?.remove()}
}
function ensureGroup(key,title,icon){let g=q(`#nav .nav-group[data-group="${key}"]`);if(g)return g;const nav=q('#nav');if(!nav)return null;g=document.createElement('div');g.className='nav-group';g.dataset.group=key;g.innerHTML=`<button type="button" class="nav-group-toggle" aria-expanded="false"><b class="nav-group-icon">${icon}</b><span>${title}</span><b class="nav-chevron">⌄</b></button><div class="nav-group-items"></div>`;q('.nav-group-toggle',g).onclick=e=>{e.preventDefault();e.stopPropagation();const open=g.classList.toggle('open');q('.nav-group-toggle',g).setAttribute('aria-expanded',open?'true':'false')};nav.appendChild(g);return g}
function groupFor(key){const group=catalog.byKey[key];return group?ensureGroup(group.key,group.title,group.icon):null}
function ensureView(id,managerOnly){if(REMOVED.has(id))return null;let v=q(`#${id}View`);if(v)return v;const w=q('.workspace');if(!w)return null;v=document.createElement('section');v.id=id+'View';v.className='view hidden'+(managerOnly?' manager-only':'');v.innerHTML='<div class="panel"><div class="prod-empty">در حال بارگذاری…</div></div>';w.appendChild(v);return v}
function navigate(id){if(REMOVED.has(id))return false;if(typeof showView==='function')showView(id);return render(id)}
function ensureButton(id,label,group,managerOnly){if(REMOVED.has(id))return null;let b=q(`#nav button[data-view="${id}"]`);if(!b){b=document.createElement('button');b.type='button';b.dataset.view=id;b.innerHTML=`<b>•</b><span>${esc(label)}</span>`}if(!b.dataset.runtimeBound){b.dataset.runtimeBound='1';b.addEventListener('click',()=>{void render(id)})}if(managerOnly)b.classList.add('manager-only');b.classList.toggle('hidden',managerOnly&&!mgr());const g=groupFor(group),box=q('.nav-group-items',g);if(box&&b.parentElement!==box)box.appendChild(b);return b}
function syncOrder(){purgeRemoved();Object.entries(ORDER).forEach(([key,ids])=>{const g=groupFor(key),box=q('.nav-group-items',g);if(!box)return;ids.forEach(id=>{const b=q(`#nav button[data-view="${id}"]`);if(b)box.appendChild(b)});g.classList.toggle('hidden',!qa(':scope>button',box).some(b=>!b.classList.contains('hidden')))})}
function panel(id,title,subtitle,html,managerOnly=true){if(REMOVED.has(id))return;const v=ensureView(id,managerOnly);if(!v)return;v.innerHTML=`<div class="panel table-panel"><div class="panel-head"><div><h3>${esc(title)}</h3><small>${esc(subtitle)}</small></div></div>${html}</div>`}
function render(id){if(REMOVED.has(id)){purgeRemoved();return Promise.resolve(false)}if(inflight.has(id))return inflight.get(id);const job=Promise.resolve().then(async()=>{try{if(window.bamcoTabs?.owns(id))return await window.bamcoTabs.render(id);if(window.bamcoConversations?.owns(id))return await window.bamcoConversations.render(id)}catch(err){panel(id,'اطلاعات دریافت نشد','',`<div class="prod-empty" role="alert">${esc(err.message||'ارتباط با سامانه برقرار نشد.')}<p><button type="button" class="ghost" data-runtime-retry="${esc(id)}">تلاش دوباره</button></p></div>`,false)}finally{inflight.delete(id)}});inflight.set(id,job);return job}
function bind(){document.addEventListener('click',e=>{const retry=e.target.closest('[data-runtime-retry]');if(!retry)return;if(REMOVED.has(retry.dataset.runtimeRetry)){purgeRemoved();return}if(typeof showView==='function')showView(retry.dataset.runtimeRetry);void render(retry.dataset.runtimeRetry)})}
function install(){if(installed)return;installed=true;purgeRemoved();NEW.forEach(([id,label,group,m])=>{ensureView(id,m);ensureButton(id,label,group,m)});syncOrder();bind();const nav=q('#nav'),workspace=q('.workspace');if(nav||workspace)new MutationObserver(records=>{if(records.some(r=>[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('#requestReportView,[data-view="requestReport"]')||n.querySelector?.('#requestReportView,[data-view="requestReport"]')))))purgeRemoved()}).observe(q('#appView')||document.body,{childList:true,subtree:true});window.bamcoProductionRuntime={navigate,render}}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install,{once:true});else install();
})();
