'use strict';
const labels={ready:'آماده',queued:'در صف',processing:'در حال ارسال',sent:'ارسال‌شده',delivered:'تحویل‌شده',failed:'خطا',cancelled:'لغوشده',pending:'در انتظار',in_review:'در حال بررسی',needs_revision:'برگشت جهت اصلاح',approved:'تأییدشده',rejected:'ردشده',awaiting:'بدون پاسخ',replied:'پاسخ داده',reminder_needed:'نیازمند یادآوری',portal:'داخل سامانه',email:'ایمیل',both:'هر دو',create:'تعریف وظیفه',update:'ویرایش',complete:'اعلام انجام',delete:'درخواست حذف'};
