const runs=new Map(),datasets=new Map();
function panel(id,html){const view=q('#'+id+'View');if(!view)return;view.innerHTML=`<div class="panel workspace-panel"><div class="panel-head"><h3>${titles[id]}</h3><div class="workspace-actions"><button class="ghost" data-tab-refresh="${id}">تازه‌سازی</button></div></div>${html}</div>`}
