  if(bucket!=='همه'){
   const due=String(t.due_state||''),b=due==='دیرکرد'?'دیرکرد':due.includes('هشدار')?'دوره هشدار':'فاقد شرایط دیرکرد';
   if(norm(b)!==norm(bucket))return false;
  }
