function profile(id){return(state.profiles||[]).find(x=>String(x.id)===String(id))||null}
function person(id){const p=profile(id);return p?.display_name||p?.full_name||p?.excel_name||p?.email||''}
function raw(value){if(value===null||value===undefined)return value;if(typeof value!=='string')return value;try{return JSON.parse(value)}catch{return value.replace(/^"|"$/g,'')}}
function isDateField(field){return ['start_date','done_date','due_date','archived_at','owner_deleted_at','created_at','updated_at'].includes(field)}
