function ownerFallback(row,task){const before=raw(row.old_data)||{},after=raw(row.new_data)||{};return after.former_owner_name||before.former_owner_name||task?.former_owner_name||''}
function ownerValue(row,side,task){const data=raw(side==='old'?row.old_data:row.new_data)||{},value=raw(side==='old'?row.old_value:row.new_value),id=value??data.owner_id;if(id){const found=person(id);if(found)return found}if(side==='new'&&(value===null||value===undefined||value==='')&&(data.owner_id===null||data.owner_id===undefined||data.owner_id===''))return'بدون متولی';const fallback=ownerFallback(row,task);if(fallback)return fallback;return id?'متولی حذف‌شده':'بدون متولی'}
function currentOwner(row,task){const after=raw(row.new_data)||{},before=raw(row.old_data)||{},id=after.owner_id??before.owner_id??task?.owner_id;if(id){const found=person(id);if(found)return found}return ownerFallback(row,task)||'بدون متولی'}
